from pymatgen.core import Composition

def adsorbate_inventory(formula_counts):
    total = Composition({})
    for formula, count in formula_counts:
        if count < 0 or int(count) != count:
            raise ValueError('Molecule counts must be nonnegative integers')
        total += Composition(formula) * int(count)
    return total.get_el_amt_dict()
